function exportFiguresToFolder(figDir, metadata, figHandles, closeAfterExport)
    % EXPORTFIGURESTOFOLDER Exports tracked figures to a folder with modern tools.
    % Uses savefig for .fig and exportgraphics for .png.
    %
    % Inputs:
    %   figDir          - Target directory
    %   metadata        - Struct generated by buildFigureMetadata
    %   figHandles      - Array of figure handles to export
    %   closeAfterExport- (Optional) Logical, whether to close figures after saving. Default: true.

    if nargin < 4 || isempty(closeAfterExport)
        closeAfterExport = true;
    end
    
    if isempty(figHandles)
        warning('exportFiguresToFolder:NoFigures', 'No figure handles provided. Skipping export.');
        return;
    end

    % Ensure output directory exists
    if ~exist(figDir, 'dir')
        mkdir(figDir);
    end
    
    for i = 1:numel(figHandles)
        fig = figHandles(i);
        
        % Get and sanitize figure name for filesystem compatibility
        figName = get(fig, 'Name');
        if isempty(figName)
            figName = sprintf('Figure_%d', fig.Number);
        end
        
        % Remove/replace illegal filename characters
        illegalChars = {'|', '/', ':', '\', '<', '>', '"', '?', '*'};
        for c = 1:numel(illegalChars)
            figName = strrep(figName, illegalChars{c}, '_');
        end
        
        % 1. Save the editable MATLAB figure (.fig)
        % 'compact' reduces file size by not saving unnecessary UI data
        figPath = fullfile(figDir, [figName, '.fig']);
        savefig(fig, figPath, 'compact');
        
        % 2. Export a high-res, publication-ready PNG
        % exportgraphics automatically crops whitespace and handles tiledlayouts
        pngPath = fullfile(figDir, [figName, '.png']);
        exportgraphics(fig, pngPath, 'Resolution', 300); 
    end
    
    % Save metadata alongside figures for reproducibility (saved once per folder)
    save(fullfile(figDir, 'metadata.mat'), 'metadata');
    
    % Close figures to prevent memory bloat during batch processing
    if closeAfterExport
        close(figHandles);
    end
end